import{_ as e,c as i,o as t,a2 as a}from"./chunks/framework.DWk9bKZf.js";const r=JSON.parse('{"title":"Phase 2: Introduce Asynchronous Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"docs/quicklinker-zeroRPM/technical-architecture/phase-2/index.md","filePath":"docs/quicklinker-zeroRPM/technical-architecture/phase-2/index.md","lastUpdated":1741722514000}');const n=e({name:"docs/quicklinker-zeroRPM/technical-architecture/phase-2/index.md"},[["render",function(e,r,n,o,s,l){return t(),i("div",null,r[0]||(r[0]=[a('<h1 id="phase-2-introduce-asynchronous-workflows" tabindex="-1">Phase 2: Introduce Asynchronous Workflows <a class="header-anchor" href="#phase-2-introduce-asynchronous-workflows" aria-label="Permalink to &quot;Phase 2: Introduce Asynchronous Workflows&quot;">​</a></h1><blockquote><p><em>Handling high-volume write operations with timeseries data</em></p></blockquote><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p><strong>Objective:</strong> Add an analytics dashboard to our URL shortener.</p><p><strong>Why This Matters:</strong> This phase forces us to handle high-write workloads using timeseries data, a common challenge in production systems.</p><h2 id="implementation-journey" tabindex="-1">Implementation Journey <a class="header-anchor" href="#implementation-journey" aria-label="Permalink to &quot;Implementation Journey&quot;">​</a></h2><h3 id="_1-naive-approach-the-learning-experience" tabindex="-1">1. Naive Approach (The Learning Experience) <a class="header-anchor" href="#_1-naive-approach-the-learning-experience" aria-label="Permalink to &quot;1. Naive Approach (The Learning Experience)&quot;">​</a></h3><ul><li><strong>Implementation:</strong> Write analytics directly to PostgreSQL on every redirect</li><li><strong>Expected Result:</strong> Performance degradation and potential system crashes under load</li><li><strong>Key Learning:</strong> Understanding the limitations of synchronous write operations at scale</li></ul><h3 id="_2-optimization-with-event-streaming" tabindex="-1">2. Optimization with Event Streaming <a class="header-anchor" href="#_2-optimization-with-event-streaming" aria-label="Permalink to &quot;2. Optimization with Event Streaming&quot;">​</a></h3><ul><li><strong>Implementation:</strong> Buffer clicks in Kafka → batch insert into TimescaleDB</li><li><strong>Architecture Benefits:</strong><ul><li>Decoupling of redirect and analytics services</li><li>Improved system resilience</li><li>Enhanced throughput for write operations</li></ul></li><li><strong>Key Learning:</strong> Effective patterns for handling high-volume events</li></ul><h3 id="_3-resilience-testing" tabindex="-1">3. Resilience Testing <a class="header-anchor" href="#_3-resilience-testing" aria-label="Permalink to &quot;3. Resilience Testing&quot;">​</a></h3><ul><li><strong>Challenge:</strong> Measure how many clicks can be buffered during a Kafka broker outage</li><li><strong>Metrics to Track:</strong><ul><li>Buffer capacity and limitations</li><li>Recovery time after service restoration</li><li>Data integrity throughout the failure scenario</li></ul></li><li><strong>Key Learning:</strong> Understanding the resilience characteristics of our event streaming architecture</li></ul><h2 id="expected-outcomes" tabindex="-1">Expected Outcomes <a class="header-anchor" href="#expected-outcomes" aria-label="Permalink to &quot;Expected Outcomes&quot;">​</a></h2><p>By the end of Phase 2, we will have:</p><ul><li>A functional analytics dashboard providing insights into URL usage</li><li>A resilient architecture that can handle high-write workloads</li><li>Empirical data on system behavior during component failures</li><li>Expertise in implementing and optimizing asynchronous workflows</li></ul>',15)]))}]]);export{r as __pageData,n as default};
